HANDS_FREE_MIC_JS = """
const MICS = new WeakMap()

function mergeChunks(chunks) {
  let length = 0
  for (const c of chunks) length += c.length
  const out = new Float32Array(length)
  let offset = 0
  for (const c of chunks) { out.set(c, offset); offset += c.length }
  return out
}

function downsample(samples, fromRate, toRate) {
  if (fromRate <= toRate) return samples
  const ratio = fromRate / toRate
  const out = new Float32Array(Math.floor(samples.length / ratio))
  for (let i = 0; i < out.length; i++) {
    const start = Math.floor(i * ratio), end = Math.min(samples.length, Math.floor((i + 1) * ratio))
    let sum = 0
    for (let j = start; j < end; j++) sum += samples[j]
    out[i] = sum / Math.max(1, end - start)
  }
  return out
}

function wavBase64(samples, rate) {
  const buffer = new ArrayBuffer(44 + samples.length * 2)
  const view = new DataView(buffer)
  const text = (offset, value) => { for (let i = 0; i < value.length; i++) view.setUint8(offset + i, value.charCodeAt(i)) }
  text(0, "RIFF"); view.setUint32(4, 36 + samples.length * 2, true); text(8, "WAVE"); text(12, "fmt ")
  view.setUint32(16, 16, true); view.setUint16(20, 1, true); view.setUint16(22, 1, true)
  view.setUint32(24, rate, true); view.setUint32(28, rate * 2, true); view.setUint16(32, 2, true)
  view.setUint16(34, 16, true); text(36, "data"); view.setUint32(40, samples.length * 2, true)
  for (let i = 0; i < samples.length; i++) {
    const v = Math.max(-1, Math.min(1, samples[i]))
    view.setInt16(44 + i * 2, v < 0 ? v * 0x8000 : v * 0x7fff, true)
  }
  const bytes = new Uint8Array(buffer)
  let binary = ""
  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000))
  return btoa(binary)
}

export default function (component) {
  const { data, parentElement, setTriggerValue } = component
  const root = parentElement.querySelector(".mic")
  const btn = parentElement.querySelector(".btn")
  const label = parentElement.querySelector(".label")
  const level = parentElement.querySelector(".level")
  if (!root || !btn) return
  let m = MICS.get(parentElement)
  if (!m) { m = { recording: false }; MICS.set(parentElement, m) }
  m.send = setTriggerValue  // the latest, for a recording that outlives a rerun
  const silenceMs = ((data && data.silence_seconds) || 3) * 1000
  const iconOnly = data && data.label === ""
  const idleText = iconOnly ? "Dictate" : (data && data.label) || "Dictate"
  root.classList.toggle("icon-only", !!iconOnly)
  const show = (state, text) => { root.dataset.state = state; label.textContent = text; if (iconOnly) btn.title = text }
  btn.title = (data && data.help) || ""
  if (!m.recording) show("idle", m.note || idleText)
  m.note = ""

  const stop = (send) => {
    if (!m.recording) return
    m.recording = false
    m.held = false  // a later key-up (e.g. after the five-minute stop) has nothing to end
    level.style.width = "0"
    try { m.proc.onaudioprocess = null; m.proc.disconnect(); m.source.disconnect() } catch (e) {}
    m.stream.getTracks().forEach((t) => t.stop())
    m.ctx.close()
    const samples = mergeChunks(m.chunks)
    m.chunks = []
    if (!send || samples.length < m.rate * 0.4) {
      show("idle", idleText)
      if (data && data.notify) m.send("stopped", Date.now())
      return
    }
    // Drop most of the closing silence: it only slows transcription.
    const keep = m.heard ? Math.max(0, samples.length - Math.floor(m.rate * Math.max(0, (performance.now() - m.lastLoud) / 1000 - 0.6))) : samples.length
    show("busy", "Sent")
    // Ready for the next one shortly (the page may not redraw the mic after the answer).
    clearTimeout(m.reset)
    m.reset = setTimeout(() => { if (!m.recording) show("idle", idleText) }, 3000)
    m.send("recording", wavBase64(downsample(samples.subarray(0, keep), m.rate, 16000), 16000))
  }

  const start = async () => {
    try {
      m.stream = await navigator.mediaDevices.getUserMedia({ audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true } })
    } catch (e) {
      m.held = false
      m.releaseWhenReady = false
      show("error", "No microphone access")
      return
    }
    m.ctx = new AudioContext()
    m.source = m.ctx.createMediaStreamSource(m.stream)
    m.proc = m.ctx.createScriptProcessor(4096, 1, 1)
    Object.assign(m, { chunks: [], rate: m.ctx.sampleRate, heard: false, floor: null, recording: true,
                       started: performance.now(), lastLoud: performance.now() })
    // The key was let go of after a long hold while the mic was still starting: send as soon as it's running.
    if (m.releaseWhenReady) { m.releaseWhenReady = false; m.held = false; setTimeout(() => stop(true), 0) }
    m.proc.onaudioprocess = (event) => {
      if (!m.recording) return
      const input = event.inputBuffer.getChannelData(0)
      m.chunks.push(new Float32Array(input))
      let sum = 0
      for (let i = 0; i < input.length; i++) sum += input[i] * input[i]
      const rms = Math.sqrt(sum / input.length)
      // Speech is well above the room's background level, which is followed slowly.
      m.floor = m.floor === null ? rms : (rms < m.floor ? rms : m.floor * 0.995 + rms * 0.005)
      const now = performance.now()
      if (rms > Math.max(0.012, m.floor * 3)) { m.heard = true; m.lastLoud = now }
      level.style.width = Math.min(100, rms * 600) + "%"
      const quiet = now - m.lastLoud
      if (now - m.started > 300000) {
        stop(true)  // five minutes at most, held or not
      } else if (m.held) {
        // Held: pauses don't end it; letting go of the key sends it.
        label.textContent = "Recording — release the key to send"
      } else if (!m.heard) {
        label.textContent = "Listening… speak now"
        if (now - m.started > 15000) { stop(false); show("idle", "Didn't hear anything") }
      } else if (quiet >= silenceMs) {
        stop(true)
      } else {
        label.textContent = quiet > 800 ? "Sending in " + Math.ceil((silenceMs - quiet) / 1000) + " s…" : "Listening… pause to send"
      }
    }
    m.source.connect(m.proc)
    m.proc.connect(m.ctx.destination)
    show("recording", "Listening… speak now")
    if (data && data.notify) m.send("started", Date.now())  // e.g. the hotkey's red bar, with Cancel
  }

  // The app's Cancel: stop listening and send nothing.
  const cancel = (data && data.cancel) || 0
  if (m.cancelSeen === undefined) m.cancelSeen = cancel
  else if (cancel !== m.cancelSeen) { m.cancelSeen = cancel; if (m.recording) stop(false) }

  btn.onclick = () => { if (m.recording) stop(true); else if (root.dataset.state !== "busy") start() }

  // The hotkey works two ways. A tap starts listening, and a pause ends it (as the mic button does). Holding it
  // (longer than HOLD_MS) records until you let go, however long you pause. Pressing it again while listening sends.
  const HOLD_MS = 600
  const keyDown = () => {
    if (m.recording) { stop(true); return }
    if (root.dataset.state === "busy") return
    m.held = true  // until the key comes up: a quick release turns it back into a tap
    m.keyDownAt = performance.now()
    m.releaseWhenReady = false
    start()
  }
  const keyUp = () => {
    if (!m.held) return
    m.held = false
    if (performance.now() - (m.keyDownAt || 0) < HOLD_MS) return  // a tap: listen until a pause, as before
    if (m.recording) stop(true)
    else m.releaseWhenReady = true  // the mic is still starting
  }

  // The dictate hotkey: one listener for the page; it presses the mic holding the key with the highest priority.
  // Typing in a box types the character as usual.
  const keys = window.__llmNotesDictateKeys || (window.__llmNotesDictateKeys = new Map())
  const hotkeys = data && data.hotkey ? [].concat(data.hotkey) : []  // one key, or several (other keyboard layouts)
  if (hotkeys.length) keys.set(parentElement, { keys: hotkeys, priority: data.hotkey_priority || 0, down: keyDown, up: keyUp })
  else keys.delete(parentElement)
  if (!window.__llmNotesDictateListener) {
    const best = (event) => {
      let found = null
      for (const [element, entry] of keys) {
        if (!element.isConnected) { keys.delete(element); continue }
        if (entry.keys.includes(event.key) && (!found || entry.priority > found.priority)) found = entry
      }
      return found
    }
    window.__llmNotesDictateListener = (event) => {
      if (event.ctrlKey || event.metaKey || event.altKey) return
      const target = event.composedPath ? event.composedPath()[0] : event.target
      if (target && (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName || ""))) return
      const entry = best(event)
      if (!entry) return
      event.preventDefault()  // held keys repeat: swallow the repeats too
      if (event.repeat) return
      window.__llmNotesDictateHeld = entry
      entry.down()
    }
    // Letting go: the mic the key went down on, even if the page has redrawn since. Leaving the window counts.
    const release = (event) => {
      const entry = window.__llmNotesDictateHeld
      if (!entry || (event.type === "keyup" && !entry.keys.includes(event.key))) return
      window.__llmNotesDictateHeld = null
      entry.up()
    }
    document.addEventListener("keydown", window.__llmNotesDictateListener, true)
    document.addEventListener("keyup", release, true)
    window.addEventListener("blur", release)
  }
  return () => { keys.delete(parentElement); if (m.recording) stop(false) }
}
"""
_hands_free_mic = st.components.v2.component(
    "hands_free_mic", html=HANDS_FREE_MIC_HTML, css=HANDS_FREE_MIC_CSS, js=HANDS_FREE_MIC_JS,
)


DICTATE_HOTKEYS = {"`": "` backtick", "§": "§ section sign", "~": "~ tilde", "\\": "\\ backslash",
                   "|": "| vertical bar", "F2": "F2", "F4": "F4", "F8": "F8", "F9": "F9"}


def dictate_hotkey() -> str | None:
    """The key that starts dictating, or None when the hotkey is off."""
    settings = load_app_settings()
    key = settings.get("dictate_hotkey") or "`"
    return key if settings.get("dictate_hotkey_enabled", True) and key in DICTATE_HOTKEYS else None


def dictate_hotkeys() -> list[str]:
    """Every key that starts dictating (the hotkey and the optional second one), or [] when the hotkey is off."""
    first = dictate_hotkey()
    if not first:
        return []
    second = load_app_settings().get("dictate_hotkey_2") or ""
    return [first] + ([second] if second in DICTATE_HOTKEYS and second != first else [])


def hotkey_markdown(key: str) -> str:
    """The key as inline code that Markdown leaves alone (a backtick needs double backticks around it)."""
    return "`` ` ``" if key == "`" else f"`{key}`"


def configured_hotkeys() -> list[str]:
    """The keys chosen (whether or not the hotkey is on), for labels."""
    settings = load_app_settings()
    keys = [settings.get("dictate_hotkey") or "`", settings.get("dictate_hotkey_2") or ""]
    return [k for i, k in enumerate(keys) if k in DICTATE_HOTKEYS and k not in keys[:i]]


def hotkeys_markdown(keys: list[str]) -> str:
    """[ ` ] or [ ` ] / [ § ]."""
    return " / ".join(f"[ {hotkey_markdown(k)} ]" for k in keys)


# Truncated dropdown text (a long library name, or Single Corpus with its date) shows in full on hover: one
# page-wide listener adds a native tooltip to whatever is cut off under the pointer in a dropdown or its list.
FULL_TEXT_TOOLTIPS_JS = """
export default function () {
  if (window.__llmNotesFullText) return
  window.__llmNotesFullText = true
  // Starred Note-Workflows: a button that doesn't fit the row's width is hidden (they're all in the menu too).
  const fitStarred = () => {
    const box = document.querySelector(".st-key-workflow_starred")
    if (!box) return
    const right = box.getBoundingClientRect().right
    for (const item of box.children) {
      item.style.visibility = ""
      if (item.getBoundingClientRect().right > right + 1) item.style.visibility = "hidden"
    }
  }
  addEventListener("resize", fitStarred)
  setInterval(fitStarred, 500)
  // Oneshot search: Enter sends it (as Cmd/Ctrl+Enter does, which saves the text first); Shift+Enter adds a line.
  document.addEventListener("keydown", (event) => {
    const box = event.target
    if (!(box.matches && box.matches(".st-key-oneshot_text textarea"))) return
    if (event.key !== "Enter" || event.shiftKey || event.altKey || event.ctrlKey || event.metaKey || event.isComposing) return
    event.preventDefault()
    event.stopImmediatePropagation()
    if (!box.value.trim()) return
    box.dispatchEvent(new KeyboardEvent("keydown", {key: "Enter", code: "Enter", keyCode: 13, which: 13,
                                                     ctrlKey: true, metaKey: true, bubbles: true, cancelable: true}))
  }, true)
  // Oneshot search grows with its text where the browser can't size it by CSS (field-sizing).
  if (!CSS.supports("field-sizing", "content")) {
    const fit = (box) => { box.style.height = "auto"; box.style.height = Math.min(box.scrollHeight + 2, innerHeight * 0.4) + "px" }
    document.addEventListener("input", (event) => {
      if (event.target.matches && event.target.matches(".st-key-oneshot_text textarea")) fit(event.target)
    }, true)
  }
  document.addEventListener("mouseover", (event) => {
    const root = event.target.closest && event.target.closest('[data-testid="stSelectbox"], [role="option"]')
    if (!root) return
    // The chosen value is in the dropdown's text box; a list option is plain text.
    const input = root.querySelector && root.querySelector("input")
    if (input && input.value && input.scrollWidth > input.clientWidth + 1) { input.title = input.value; return }
    for (let el = event.target; el && el !== root.parentElement; el = el.parentElement) {
      if (el.scrollWidth > el.clientWidth + 1 && el.textContent.trim()) { el.title = el.textContent.trim(); return }
    }
  }, true)
}
"""
_full_text_tooltips = st.components.v2.component("full_text_tooltips", html="<span></span>", js=FULL_TEXT_TOOLTIPS_JS)


# --- Notifications: LLM work that finishes while you're away from the tab --------------------------------------
NOTIFY_SETTING = "notify_when_away"
NOTIFICATIONS_SETTING = "notifications_enabled"  # the app's own off switch for every notification
NOTIFY_TEST_DELAY = 10  # seconds: Send in 10 s, to switch to another app and see it arrive
NOTIFY_PENDING_KEY = "task_notification"  # {id, title, body}: shown by the notifier (in the sidebar) once
NOTIFY_CONTEXT_KEY = "task_notify_as"  # what the LLM call running now is for, e.g. "Answer ready · Search: CorpA"
NOTIFY_MIN_SECONDS = 8  # quicker work isn't worth a notification (you're likely still looking)
TASK_NOTIFIER_JS = """
export default function (component) {
  const { data } = component
  if (!data || !data.enabled || !("Notification" in window)) return
  const shown = window.__llmNotesShown || (window.__llmNotesShown = new Set())
  // The browser asks once, on your next click on the page (it only allows asking from a click).
  if (!window.__llmNotesAsk && Notification.permission === "default") {
    window.__llmNotesAsk = true
    const ask = () => {
      document.removeEventListener("click", ask, true)
      if (Notification.permission === "default") Notification.requestPermission()
    }
    document.addEventListener("click", ask, true)
  }
  const note = data.note
  if (!note || shown.has(note.id)) return
  shown.add(note.id)
  // Only when you're not looking at this tab (another tab, another app, or the window minimised).
  if (document.visibilityState === "visible" && document.hasFocus()) return
  if (Notification.permission !== "granted") return
  const n = new Notification(note.title, { body: note.body, tag: "llm-notes-task" })
  n.onclick = () => { window.focus(); n.close() }  // brings this tab (and its window) to the front
}
"""
_task_notifier = st.components.v2.component("task_notifier", html="<span></span>", js=TASK_NOTIFIER_JS)


@contextmanager
def notify_as(text: str):
    """What a notification says if the LLM work inside finishes while you're away (no note content)."""
    before = st.session_state.get(NOTIFY_CONTEXT_KEY)
    st.session_state[NOTIFY_CONTEXT_KEY] = text
    try:
        yield
    finally:
        st.session_state[NOTIFY_CONTEXT_KEY] = before


def default_notify_text() -> str:
    page = st.query_params.get("page") or ""
    if page == CHAT_PAGE:
        return "Chat: the reply is ready"
    if page:
        return "Your task has finished"
    library = st.session_state.get("selected_library")
    return f"Answer ready · Search: {library}" if library else "Answer ready"


def queue_task_notification(body: str | None = None, seconds: float | None = None) -> None:
    """Queue a notification for finished LLM work, shown by the notifier only if you're away from the tab.
    `seconds`: how long it took (quick work is skipped). Never from a worker thread (no session there)."""
    from streamlit.runtime.scriptrunner import get_script_run_ctx

    if get_script_run_ctx() is None or (seconds is not None and seconds < NOTIFY_MIN_SECONDS):
        return
    if not notifications_enabled():
        return
    st.session_state[NOTIFY_PENDING_KEY] = {
        "id": uuid.uuid4().hex, "title": "LLM-Notes",
        "body": body or st.session_state.get(NOTIFY_CONTEXT_KEY) or default_notify_text()}


def notify_index_finished(action: str, library: str, started: float, job_status: dict | None = None,
                          failed: bool = False) -> None:
    """Queue a notification for a rebuild or rescan that finished (or failed) while you're away. Names the
    library and counts only, never note content."""
    if failed:
        body = f"{action} of {library} failed — open the app to see why"
    else:
        vectors = int((job_status or {}).get("vectors") or 0)
        body = f"{action} of {library} has finished" + (f" · {vectors:,} vectors" if vectors else "")
    queue_task_notification(body, time.monotonic() - started)


@st.fragment(run_every=4)
def render_task_notifier(enabled: bool) -> None:
    """In the sidebar: hands the browser the latest finished task. It refreshes by itself every few seconds (it
    waits for a running page to finish, never cutting it short), so a task that ends a page run is still shown."""
    note = st.session_state.pop(NOTIFY_PENDING_KEY, None)
    _task_notifier(key="task_notifier", data={"enabled": enabled, "note": note if enabled else None})


def install_task_notifier() -> None:
    """On every page, out of sight in the sidebar: the notifier for LLM work that finishes while you're away."""
    with st.sidebar, st.container(key="task_notifier_box"):
        st.html("<style>.st-key-task_notifier_box { position: absolute !important; height: 0 !important; "
                "overflow: hidden; pointer-events: none; }</style>")
        render_task_notifier(notifications_enabled() and bool(load_app_settings().get(NOTIFY_SETTING, True)))


def notifications_enabled() -> bool:
    """The app's own switch (Configure > Notifications): off, it sends none, tests included."""
    return bool(load_app_settings().get(NOTIFICATIONS_SETTING, True))


# The Configure page's test notifications: shown whether or not you're looking at the tab, now or after a delay
# (timed in the browser, so switching to another app doesn't stop it). The browser asks to allow them first if it
# hasn't yet; the line under the buttons says what it allows.
NOTIFY_TEST_JS = """
export default function (component) {
  const { data, parentElement } = component
  const status = parentElement.querySelector(".nt")
  const say = (text) => { if (status) status.textContent = text }
  if (!("Notification" in window)) { say("This browser can't show notifications."); return }
  const states = { granted: "The browser allows notifications from this app.",
                   denied: "The browser blocks notifications from this app: allow them for this site in the browser's settings.",
                   default: "The browser hasn't been asked yet: a test asks it first." }
  say(states[Notification.permission] || "")
  const test = data && data.test
  const sent = window.__llmNotesTests || (window.__llmNotesTests = new Set())
  if (!test || sent.has(test.id)) return
  sent.add(test.id)
  const show = () => {
    const n = new Notification(test.title, { body: test.body, tag: "llm-notes-test" })
    n.onclick = () => { window.focus(); n.close() }
    say(test.delay ? "Sent." : states.granted)
  }
  const go = async () => {
    // The notifier on every page asks on a click (the browser only allows asking from one), so pressing the
    // test button usually asks; this is a second try for browsers that allow asking without a click.
    if (Notification.permission === "default") { try { await Notification.requestPermission() } catch (e) {} }
    say(states[Notification.permission] || "")
    if (Notification.permission !== "granted") return
    if (!test.delay) { show(); return }
    let left = test.delay
    say("Sending in " + left + " s… switch to another app to see it arrive.")
    const tick = setInterval(() => {
      left -= 1
      if (left > 0) { say("Sending in " + left + " s… switch to another app to see it arrive."); return }
      clearInterval(tick)
      show()
    }, 1000)
  }
  go()
}
"""
_notify_test = st.components.v2.component(
    "notify_test", html='<div class="nt"></div>', js=NOTIFY_TEST_JS,
    css=".nt { font-size: 0.875rem; color: var(--st-text-color); opacity: 0.7; }",
)
NOTIFY_TEST_KEY = "notify_test"  # {id, title, body, delay}: the test the Configure page sends next


