PAGE_TITLES = {
    "prompts": "RAG - Prompt library",
    "actions": "RAG - Actions",
    "configure": "RAG - Configure",
    "reference": "RAG - Reference document",
    CHAT_PAGE: "RAG - Chat with LLM",
}
st.set_page_config(page_title=PAGE_TITLES.get(st.query_params.get("page"), "RAG Workspace Manager"),
                   layout="wide")
# Starts the background auto-rescan thread once per server process.
get_text_rescan_scheduler()
start_hold_release_thread()  # releases packages held for review into the outbox on time
_dictated = st.session_state.pop(DICTATED_KEY, None)  # set by the run that sent a dictated message
if st.session_state.pop(LLM_CANCELLED_KEY, False):
    if _dictated:
        restore_after_stop(_dictated)
        st.toast("Stopped. Your dictated text is back in its box: edit it and send again.", icon=":material/edit:")
    else:
        st.toast("Stopped the LLM. Change what you need and run it again.", icon=":material/stop_circle:")
if not st.session_state.get("landing_page_chosen"):
    st.session_state["landing_page_chosen"] = True
    if not st.query_params.get("page") and load_app_settings().get("open_on_chat"):
        st.query_params["page"] = CHAT_PAGE
if st.session_state.pop(TRANSCRIPTION_CANCELLED_KEY, False):
    st.toast("Cancelled. Nothing was sent.", icon=":material/close:")
install_task_notifier()  # before the pages split, so every page has it
if st.query_params.get("page") == CHAT_PAGE:
    render_chat_page()
    st.stop()
forget_in_confidence_chat()  # however Chat was left
render_dictate_to_chat()
if st.query_params.get("page") == "prompts":
    render_prompt_library_page()
    st.stop()
if st.query_params.get("page") == "actions":
    render_actions_page()
    st.stop()
if st.query_params.get("page") == "configure":
    render_configure_page()
    st.stop()
if st.query_params.get("page") == "reference":
    render_reference_page()
    st.stop()
start_pending_oneshot()
_notes_plan = st.session_state.get(NOTES_SEARCH_KEY)
if _notes_plan and not _notes_plan.get("applied"):  # a Chat message moved here: fill in its search
    apply_notes_search(_notes_plan)
    _notes_plan["applied"] = True
apply_notes_run_step()

render_outbox_status()
st.title("🧠 RAG Workspace Manager")

if should_show_setup_wizard():
    render_setup_wizard()
    st.stop()

